'use strict';
const $=id=>document.getElementById(id), KEY='clientdesk.workspace.v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dayOffset=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const cash=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const uid=()=>crypto.randomUUID();
const initial=()=>({demo:true,clients:[{id:'c1',name:'Olive & Oak',email:'hello@olive.example',company:'Lifestyle & interiors',notes:'Brand identity and ecommerce experience.'},{id:'c2',name:'Forma Studio',email:'team@forma.example',company:'Architecture & design',notes:'A thoughtful portfolio for an independent studio.'},{id:'c3',name:'Northstar',email:'work@northstar.example',company:'Technology',notes:'Product launch and website.'},{id:'c4',name:'Bloom Coffee',email:'hello@bloom.example',company:'Food & beverage',notes:'Digital presence for a neighborhood café.'}],projects:[{id:'p1',name:'E-commerce experience',client:'c1',budget:45000,due:dayOffset(5),status:'progress',notes:'Product pages, storefront and checkout design.'},{id:'p2',name:'Studio portfolio website',client:'c2',budget:32000,due:dayOffset(2),status:'review',notes:'Final design review before handoff.'},{id:'p3',name:'SaaS landing page',client:'c3',budget:28000,due:dayOffset(12),status:'todo',notes:'Discovery, wireframes and responsive implementation.'},{id:'p4',name:'Brand identity system',client:'c4',budget:18000,due:dayOffset(-3),status:'done',notes:'Logo, colors and social assets delivered.'},{id:'p5',name:'Monthly design support',client:'c1',budget:12000,due:dayOffset(8),status:'progress',notes:'Campaign banners and product photography layouts.'}],invoices:[{id:'i1',number:'INV-001',client:'c1',description:'Storefront design — milestone 1',amount:22500,due:dayOffset(-20),status:'paid',paid:dayOffset(-24)},{id:'i2',number:'INV-002',client:'c4',description:'Brand identity — final delivery',amount:18000,due:dayOffset(-3),status:'paid',paid:dayOffset(-5)},{id:'i3',number:'INV-003',client:'c2',description:'Portfolio website — balance',amount:16000,due:dayOffset(4),status:'sent',paid:''},{id:'i4',number:'INV-004',client:'c3',description:'Discovery and design deposit',amount:14000,due:dayOffset(-2),status:'sent',paid:''}]});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}
const statuses={todo:'To do',progress:'In progress',review:'In review',done:'Completed'};
const navs=[['dashboard','◫','Overview'],['clients','♧','Clients'],['projects','▦','Projects'],['invoices','▤','Invoices'],['reports','↗','Reports'],['settings','⚙','Settings']];
let route='dashboard',query='',filter='all';
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Storage unavailable. Export a backup to keep your changes.');return false}}
function client(id){return state.clients.find(c=>c.id===id)?.name||'Unassigned'}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase()}
function badge(status){return `<span class="pill ${esc(status)}">${esc(statuses[status]||status[0].toUpperCase()+status.slice(1))}</span>`}
function invoiceStatus(i){return i.status==='sent'&&i.due<today()?'overdue':i.status}
function head(title,sub,action,type){return `<div class="page-head"><div><div class="eyebrow">YOUR INDEPENDENT WORKSPACE${state.demo?'<span class="demo">Demo data</span>':''}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action?`<button class="primary" data-new="${type}">+ &nbsp; ${action}</button>`:''}</div>`}
function stats(){const paid=state.invoices.filter(i=>i.status==='paid').reduce((s,i)=>s+i.amount,0),pending=state.invoices.filter(i=>i.status==='sent').reduce((s,i)=>s+i.amount,0);return `<div class="stats">${[['Total collected',cash(paid),'↗','Paid invoices · all time'],['Active projects',state.projects.filter(p=>p.status!=='done').length,'▦','Your work in motion'],['Outstanding',cash(pending),'◷','Sent invoices awaiting payment'],['Total clients',state.clients.length,'♧','Relationships worth building']].map(([t,v,icon,n])=>`<article class="stat"><label>${t}<span>${icon}</span></label><strong>${v}</strong><small>${n}</small></article>`).join('')}</div>`}
function revenueChart(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return {label:d.toLocaleString('en',{month:'short'}),value:state.invoices.filter(x=>x.status==='paid'&&(x.paid||'').startsWith(key)).reduce((s,x)=>s+x.amount,0)}});const max=Math.max(...months.map(x=>x.value),1);return `<div class="chart" role="img" aria-label="Collected revenue for the last six months">${months.map(m=>`<div class="bar-group"><span class="value">${m.value?cash(m.value):'—'}</span><div class="bar" style="height:${Math.max(2,m.value/max*125)}px"></div><small>${m.label}</small></div>`).join('')}</div><div class="chart-footer">Based on payment dates · ${cash(months.reduce((s,m)=>s+m.value,0))} collected over six months</div>`}
function projectTable(projects){return projects.length?`<div class="table-wrap"><table><thead><tr><th>PROJECT NAME</th><th>CLIENT</th><th>STATUS</th><th>DUE DATE</th><th>VALUE</th><th></th></tr></thead><tbody>${projects.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(client(p.client))}</td><td>${badge(p.status)}</td><td>${esc(p.due)}</td><td>${cash(p.budget)}</td><td><button class="text-btn" data-edit="project" data-id="${p.id}">Edit ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No projects yet. Create your first project to get started.</div>'}
function dashboard(){const due=state.projects.filter(p=>p.status!=='done').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);return head('A little clarity. A lot of possibility.','Welcome back, Adarsh. Here’s how your business is shaping up.','New project','project')+`<div class="hero"><div><span class="eyebrow">YOUR STUDIO, IN SYNC</span><h2>Good work starts with a clear head.</h2><p>You have ${state.projects.filter(p=>p.status!=='done').length} projects in motion. Keep your clients close, your deadlines closer, and make space for what you do best.</p><a href="#projects" class="text-btn">Take a look at your projects &nbsp; ↗</a></div><div class="hero-art" aria-hidden="true">✳</div></div>`+stats()+`<div class="grid"><section class="panel"><div class="section-head"><h2>Revenue overview</h2><span class="legend"><b>●</b> &nbsp; Collected · Last 6 months</span></div>${revenueChart()}</section><section class="panel"><div class="section-head"><h2>Coming up next</h2><a href="#projects">View all ↗</a></div>${due.map(p=>`<div class="deadline"><div class="date-box">${Number(p.due.slice(8))}<small>${new Date(p.due+'T12:00:00').toLocaleString('en',{month:'short'}).toUpperCase()}</small></div><div><h3>${esc(p.name)}</h3><p>${esc(client(p.client))} · ${p.due<today()?'Past due':statuses[p.status]}</p></div></div>`).join('')||'<p class="empty">A clear calendar. Start something great.</p>'}</section></div><section class="panel"><div class="section-head"><h2>Projects in focus</h2><a href="#projects">All projects ↗</a></div>${projectTable(state.projects.slice(0,5))}</section>`}
function tools(placeholder,options){return `<div class="tools"><input id="search" aria-label="Search" placeholder="Search ${placeholder}…" value="${esc(query)}">${options?`<select id="filter" aria-label="Filter status">${Object.entries(options).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select>`:''}</div>`}
function clients(){const list=state.clients.filter(c=>(c.name+' '+c.company+' '+c.email).toLowerCase().includes(query.toLowerCase()));return head('Great work. Better relationships.','A home for every client, conversation, and collaboration.','New client','client')+tools('clients')+`<div class="client-grid">${list.map(c=>`<article class="client-card"><span class="avatar">${esc(initials(c.name))}</span><h3>${esc(c.name)}</h3><p>${esc(c.company)}</p><p>${esc(c.email)}</p><p>${esc(c.notes)}</p><div class="client-meta"><span>${state.projects.filter(p=>p.client===c.id).length} projects</span><button class="text-btn" data-edit="client" data-id="${c.id}">Manage client ↗</button></div></article>`).join('')||'<p class="empty">No clients found.</p>'}</div>`}
function projects(){const list=state.projects.filter(p=>(p.name+' '+client(p.client)).toLowerCase().includes(query.toLowerCase()));return head('From first idea to final handoff.','Move work forward, one thoughtful step at a time.','New project','project')+tools('projects')+`<div class="board">${Object.entries(statuses).map(([status,label])=>`<section class="column"><h3>${label} &nbsp; <span class="legend">${list.filter(p=>p.status===status).length}</span></h3>${list.filter(p=>p.status===status).map(p=>`<article class="task"><span class="pill">${esc(client(p.client))}</span><h3>${esc(p.name)}</h3><p>${esc(p.notes)}</p><div class="amount">${cash(p.budget)}</div><div class="task-bottom"><small>◷ ${esc(p.due)}</small><button class="text-btn" data-edit="project" data-id="${p.id}">Edit</button></div><select aria-label="Stage for ${esc(p.name)}" data-stage="${p.id}">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${k===p.status?'selected':''}>${v}</option>`).join('')}</select></article>`).join('')||'<p class="empty">Room for what’s next.</p>'}</section>`).join('')}</div>`}
function invoices(){const list=state.invoices.filter(i=>(i.number+' '+client(i.client)).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||invoiceStatus(i)===filter));return head('Get paid for your good work.','Create invoices, track payment status, and print a clean PDF.','New invoice','invoice')+stats()+tools('invoices',{all:'All statuses',draft:'Draft',sent:'Sent',overdue:'Overdue',paid:'Paid'})+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>INVOICE</th><th>CLIENT</th><th>AMOUNT</th><th>DUE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${list.map(i=>`<tr><td><strong>${esc(i.number)}</strong><small>${esc(i.description)}</small></td><td>${esc(client(i.client))}</td><td>${cash(i.amount)}</td><td>${i.due}</td><td>${badge(invoiceStatus(i))}</td><td><button class="text-btn" data-edit="invoice" data-id="${i.id}">Edit</button> <button class="text-btn" data-print="${i.id}">Print / PDF</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<p class="empty">No invoices found.</p>'}</section>`}
function reports(){return head('The bigger picture.','Understand the value of your work and the health of your pipeline.')+stats()+`<div class="grid"><section class="panel"><h2>Collected revenue</h2>${revenueChart()}</section><section class="panel"><h2>Project pipeline value</h2><div class="report-big">${cash(state.projects.filter(p=>p.status!=='done').reduce((s,p)=>s+p.budget,0))}</div><p class="subtitle">Combined budgets of active projects. This is potential value, not collected income.</p>${Object.entries(statuses).map(([k,v])=>`<div class="deadline"><span>${v}</span><strong style="margin-left:auto">${cash(state.projects.filter(p=>p.status===k).reduce((s,p)=>s+p.budget,0))}</strong></div>`).join('')}</section></div><section class="panel"><h2>Revenue by client</h2><div class="table-wrap"><table><thead><tr><th>CLIENT</th><th>PROJECTS</th><th>COLLECTED</th><th>OUTSTANDING</th></tr></thead><tbody>${state.clients.map(c=>`<tr><td>${esc(c.name)}</td><td>${state.projects.filter(p=>p.client===c.id).length}</td><td>${cash(state.invoices.filter(i=>i.client===c.id&&i.status==='paid').reduce((s,i)=>s+i.amount,0))}</td><td>${cash(state.invoices.filter(i=>i.client===c.id&&i.status==='sent').reduce((s,i)=>s+i.amount,0))}</td></tr>`).join('')}</tbody></table></div></section>`}
function settings(){return head('Make this space yours.','Your workspace, your data, your way of working.')+`<div class="settings-grid"><section class="panel"><h2>Workspace storage</h2><p>Your clients, projects, and invoices are saved in this browser on this device. Download a backup before switching devices or clearing browser data. This version has no cloud sync or shared client access.</p><button class="primary" id="export-data">Download backup</button> <button class="secondary" id="import-data">Restore backup</button><input id="restore" type="file" accept="application/json" hidden></section><section class="panel"><h2>A fresh start</h2><p>${state.demo?'You are exploring sample clients and projects. Clear the demo workspace to start managing your own business.':'Clear all workspace records. Download a backup first if you want to keep them.'}</p><button class="secondary" id="clear-data">${state.demo?'Clear demo data':'Clear workspace'}</button></section><section class="panel"><h2>Built to grow with you</h2><p>Current tools: client records, project stages, invoices, print-to-PDF, reports, and backups. Invoices are single-line documents; sending email, collecting payments, cloud accounts, and a shared client portal are not connected in this version.</p></section></div>`}
function render(){route=location.hash.slice(1)||'dashboard';if(!navs.some(n=>n[0]===route))route='dashboard';$('nav').innerHTML=navs.map(([id,icon,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span>${icon}</span>${label}</a>`).join('');$('breadcrumb').textContent=navs.find(n=>n[0]===route)[2];$('main').innerHTML=({dashboard,clients,projects,invoices,reports,settings})[route]();bind()}
function field(label,name,value='',type='text',options){return `<label for="f-${name}">${label}</label>${options?`<select id="f-${name}" name="${name}" required>${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${String(value)===k?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${name}" name="${name}" maxlength="1000">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0.01" max="1000000000" step="0.01"':''} maxlength="160" required>`}`}
function openEditor(type,id){if(type!=='client'&&!state.clients.length){toast('Add a client first to link your work.');openEditor('client');return}const key=type==='client'?'clients':type==='project'?'projects':'invoices',record=state[key].find(x=>x.id===id)||{};$('modal-title').textContent=(id?'Edit ':'New ')+type;const clientOptions=Object.fromEntries(state.clients.map(c=>[c.id,c.name]));let html='';if(type==='client')html=field('Client name','name',record.name)+field('Email address','email',record.email,'email')+field('Company / industry','company',record.company)+field('Notes','notes',record.notes,'textarea');if(type==='project')html=field('Project name','name',record.name)+field('Client','client',record.client,'text',clientOptions)+field('Project budget (INR)','budget',record.budget,'number')+field('Due date','due',record.due||dayOffset(7),'date')+field('Stage','status',record.status||'todo','text',statuses)+field('Project notes','notes',record.notes,'textarea');if(type==='invoice')html=field('Invoice number','number',record.number||'INV-'+String(state.invoices.length+1).padStart(3,'0'))+field('Client','client',record.client,'text',clientOptions)+field('Service / line item','description',record.description)+field('Amount (INR)','amount',record.amount,'number')+field('Due date','due',record.due||dayOffset(14),'date')+field('Status','status',record.status||'draft','text',{draft:'Draft',sent:'Sent (mark manually)',paid:'Paid'})+field('Payment date (used when paid)','paid',record.paid||today(),'date');if(id)html+=`<p><button type="button" class="text-btn" id="delete-record" style="color:#b35e49">Delete ${type}</button></p>`;$('fields').innerHTML=html;$('editor').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));for(const k in data)data[k]=data[k].trim();if(type==='client'&&!data.name){toast('Enter a client name.');return}if(type==='invoice'&&state.invoices.some(i=>i.id!==id&&i.number===data.number)){toast('Invoice number already exists.');return}if(type==='project')data.budget=Number(data.budget);if(type==='invoice'){data.amount=Number(data.amount);if(data.status!=='paid')data.paid=''}data.id=id||uid();if(id)state[key]=state[key].map(x=>x.id===id?data:x);else state[key].push(data);const saved=save();$('modal').close();render();if(saved)toast(type[0].toUpperCase()+type.slice(1)+' saved')};if(id)$('delete-record').onclick=()=>{if(type==='client'&&(state.projects.some(p=>p.client===id)||state.invoices.some(i=>i.client===id))){toast('Remove linked projects and invoices before deleting this client.');return}if(confirm('Delete this '+type+'?')){state[key]=state[key].filter(x=>x.id!==id);save();$('modal').close();render()}};$('modal').showModal()}
function backup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ClientDesk-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function printInvoice(id){const i=state.invoices.find(x=>x.id===id),c=state.clients.find(x=>x.id===i.client);document.querySelector('.print-sheet')?.remove();const div=document.createElement('div');div.className='print-sheet';div.innerHTML=`<h1>INVOICE</h1><p>${esc(i.number)}</p><hr><h2>Adarsh Murali</h2><p>Bill to: ${esc(c.name)}<br>${esc(c.email)}</p><p>Due: ${i.due}<br>Status: ${esc(invoiceStatus(i))}</p><table><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody><tr><td>${esc(i.description)}</td><td>${cash(i.amount)}</td></tr><tr><td><strong>Total (INR)</strong></td><td><strong>${cash(i.amount)}</strong></td></tr></tbody></table><p>Thank you for your business.</p>`;document.body.append(div);window.print()}
function validBackup(s){if(!s||!['clients','projects','invoices'].every(k=>Array.isArray(s[k])&&s[k].length<=10000))return false;const str=(v,max=1000)=>typeof v==='string'&&v.length<=max;const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v));const ids=new Set();for(const k of ['clients','projects','invoices'])for(const r of s[k]){if(!r||!str(r.id,100)||!/^[a-zA-Z0-9-]+$/.test(r.id)||ids.has(r.id))return false;ids.add(r.id)}return s.clients.every(c=>['name','email','company','notes'].every(k=>str(c[k])))&&s.projects.every(p=>str(p.name)&&str(p.notes)&&s.clients.some(c=>c.id===p.client)&&Object.hasOwn(statuses,p.status)&&validDate(p.due)&&Number.isFinite(p.budget)&&p.budget>0)&&s.invoices.every(i=>str(i.number)&&str(i.description)&&s.clients.some(c=>c.id===i.client)&&['draft','sent','paid'].includes(i.status)&&validDate(i.due)&&(i.status!=='paid'||validDate(i.paid))&&Number.isFinite(i.amount)&&i.amount>0)}
function bind(){document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openEditor(b.dataset.new));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit,b.dataset.id));document.querySelectorAll('[data-stage]').forEach(s=>s.onchange=()=>{state.projects.find(p=>p.id===s.dataset.stage).status=s.value;save();render()});document.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>printInvoice(b.dataset.print));if($('search'))$('search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('search').focus();$('search').setSelectionRange(pos,pos)};if($('filter'))$('filter').onchange=e=>{filter=e.target.value;render()};if($('export-data'))$('export-data').onclick=backup;if($('clear-data'))$('clear-data').onclick=()=>{if(confirm('Clear all clients, projects, and invoices on this device?')){state={demo:false,clients:[],projects:[],invoices:[]};save();render();toast('Your fresh workspace is ready.')}};if($('import-data')){$('import-data').onclick=()=>$('restore').click();$('restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();const parsed=JSON.parse(await file.text());if(!validBackup(parsed))throw Error();if(confirm('Replace current workspace with this backup?')){state=parsed;save();render();toast('Backup restored.')}}catch{toast('This is not a valid ClientDesk backup.')}}}}
$('close').onclick=$('cancel').onclick=()=>$('modal').close();$('backup').onclick=backup;$('theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('clientdesk.theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};try{if(localStorage.getItem('clientdesk.theme')==='dark')document.body.classList.add('dark')}catch{}
window.onhashchange=()=>{query='';filter='all';render()};render();
